-- ADR 0087 lot c (SEC-16): the daily statistics of a creator are written by the hourly reading under the app role,
-- one creator and one transaction at a time (withTenantJob, app.job = 'daily_stats'), no longer by the service role
-- across all of them. Additive for the app role: policies that only this job passes (no account's session sets
-- app.job), and the rights its upsert needs. The service role keeps the read and loses the write.
CREATE POLICY "job_read" ON "platform_chatter_daily_stats" AS PERMISSIVE FOR SELECT TO public USING ("platform_chatter_daily_stats"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'daily_stats');--> statement-breakpoint
CREATE POLICY "job_insert" ON "platform_chatter_daily_stats" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("platform_chatter_daily_stats"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'daily_stats');--> statement-breakpoint
CREATE POLICY "job_update" ON "platform_chatter_daily_stats" AS PERMISSIVE FOR UPDATE TO public USING ("platform_chatter_daily_stats"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'daily_stats') WITH CHECK ("platform_chatter_daily_stats"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'daily_stats');--> statement-breakpoint
CREATE POLICY "job_read" ON "platform_daily_stats" AS PERMISSIVE FOR SELECT TO public USING ("platform_daily_stats"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'daily_stats');--> statement-breakpoint
CREATE POLICY "job_insert" ON "platform_daily_stats" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("platform_daily_stats"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'daily_stats');--> statement-breakpoint
CREATE POLICY "job_update" ON "platform_daily_stats" AS PERMISSIVE FOR UPDATE TO public USING ("platform_daily_stats"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'daily_stats') WITH CHECK ("platform_daily_stats"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'daily_stats');--> statement-breakpoint
-- The upsert: a new day, or the counters of a day written over. Never the day's keys nor its creator.
GRANT INSERT ON "platform_daily_stats", "platform_chatter_daily_stats" TO nirvana_app;--> statement-breakpoint
GRANT UPDATE ("new_subscribers", "unsubscribes", "active_subscribers", "renewals", "ppv_sent", "ppv_purchased", "messages_sent", "messages_received", "read_at") ON "platform_daily_stats" TO nirvana_app;--> statement-breakpoint
GRANT UPDATE ("ppv_sent", "ppv_purchased", "messages_sent", "read_at") ON "platform_chatter_daily_stats" TO nirvana_app;--> statement-breakpoint
REVOKE INSERT, UPDATE ON "platform_daily_stats", "platform_chatter_daily_stats" FROM impera_service;
